std::string GltfDocument::Text(ryml::ConstNodeRef node){if(!node.has_val())throw std::invalid_argument("Expected glTF scalar");auto s=node.val();return {s.str,s.len};}
unsigned GltfDocument::Index(ryml::ConstNodeRef node){auto text=Text(node);std::istringstream in(text);in.imbue(std::locale::classic());unsigned long long value;if(!(in>>value)||in.peek()!=std::char_traits<char>::eof()||value>Budget)throw std::invalid_argument("Invalid glTF index");return unsigned(value);}
unsigned GltfDocument::Field(ryml::ConstNodeRef node,const char* name,unsigned fallback){return node.has_child(name)?Index(node[name]):fallback;}
GltfDocument::GltfDocument(const std::filesystem::path& path):GltfDocument(Read(path),path){}
